Rotating a region between $x=g(y)$ and the $y$-axis from $y=c$ to $y=d$ about the $y$-axis gives $V=\pi\int_{c}^{d}x^{2}\,dy$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.1cm, y=1.1cm]
\fill[gray!35] (0,1) -- plot[domain=1:3, samples=60, variable=\y] ({0.4*\y*\y+0.3},{\y}) -- (0,3) -- cycle;
\draw[->] (-1.4,0) -- (4.8,0) node[right] {$x$};
\draw[->] (0,-0.8) -- (0,4.4) node[above] {$y$};
\draw[thick, <->, domain=0.2:3.4, samples=60, variable=\y] plot ({0.4*\y*\y+0.3},{\y}) node[pos=0.98, right] {$x=g(y)$};
\draw[dashed] (0,2) ellipse [x radius=1.9, y radius=0.22];
\node[left] at (0,1) {$c$};
\node[left] at (0,3) {$d$};
\end{tikzpicture}
[/tikz]

